#!/usr/bin/env bash
# Homebrew end-to-end test of the release formula, on the archives of a
# snapshot (make snapshot), with the real Homebrew of the machine:
#
#   1. the formula is generated by Hephaestus from the brews entry of
#      hephaestus.yaml, unchanged except for its download URL (file:// URLs
#      of the snapshot archives instead of the GitHub release);
#   2. brew style, brew audit --strict, brew install, brew test;
#   3. the installed ark runs, and its bash, zsh and fish completions are
#      installed where Homebrew loads them, byte for byte the scripts of
#      misc/completions, under the names of the GoReleaser formula;
#   4. brew uninstall leaves nothing of ark behind.
#
# Usage: homebrew-e2e.sh <dist-dir>
# Environment: HEPHAESTUS (the command that runs Hephaestus; default
# "hephaestus").
#
# It installs into the machine's Homebrew prefix, in a throw-away tap, and
# removes what it created on exit: meant for CI runners and containers.
set -euo pipefail
export LC_ALL=C

dist=$(cd "${1:?usage: homebrew-e2e.sh <dist-dir>}" && pwd)
repo=$(cd "$(dirname "$0")/../.." && pwd)
read -r -a heph <<<"${HEPHAESTUS:-hephaestus}"
version=0.0.0-SNAPSHOT
tap="ark-e2e/t$RANDOM$RANDOM"
work=$(mktemp -d)

export HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_DEVELOPER=1 \
  HOMEBREW_NO_INSTALL_CLEANUP=1 HOMEBREW_NO_INSTALLED_DEPENDENTS_CHECK=1 \
  HOMEBREW_NO_ANALYTICS=1 HOMEBREW_NO_ENV_HINTS=1 HOMEBREW_NO_ASK=1

# Homebrew 7.0.11 and later load a formula of a tap that is not official only
# once it is trusted (brew trust): brew audit refuses the formula of an
# untrusted tap. Only the throw-away tap is trusted, while it exists (when
# this Homebrew has brew trust); brew untrust also forgets the formula brew
# install trusts.
trusts=false
brew trust --help >/dev/null 2>&1 && trusts=true

cleanup() {
  set +e
  brew uninstall --force "$tap/ark" >/dev/null 2>&1
  if [[ "$trusts" == true ]]; then brew untrust --tap "$tap" >/dev/null 2>&1; fi
  brew untap --force "$tap" >/dev/null 2>&1
  rm -rf "$work"
}
trap cleanup EXIT

step() { printf '\n==> %s\n' "$*"; }
fail() { echo "::error::homebrew-e2e: $*"; exit 1; }

if brew list --formula ark >/dev/null 2>&1; then
  fail "a formula named ark is already installed; this test would replace it"
fi

step "Formula from hephaestus.yaml, with file:// URLs of the snapshot archives"
# The project (the formula's desc, homepage and license) and brews sections of
# hephaestus.yaml, as they are; the snapshot archives imported as they are.
proj="$work/project"
mkdir -p "$proj/archives"
cp "$dist"/ark_${version}_{darwin,linux}_{amd64,arm64}.tar.gz "$proj/archives/"
section() { awk -v key="$1" '/^[^ #]/ { on = ($0 == key ":") } on' "$repo/hephaestus.yaml"; }
{
  echo "version: 1"
  section project
  cat <<EOF
builds:
  - id: snapshot
    targets:
      - {os: darwin, arch: amd64}
      - {os: darwin, arch: arm64}
      - {os: linux, arch: amd64}
      - {os: linux, arch: arm64}
    existing:
      kind: archive
      path: "archives/ark_${version}_{{ .OS }}_{{ .Arch }}.tar.gz"
EOF
  section brews | awk -v url="file://$proj/archives/{{ .ArtifactName }}" '
    { print }
    $0 == "  - name: ark" { print "    url_template: \"" url "\""; n++ }
    END { if (n != 1) exit 1 }'
} >"$proj/hephaestus.yaml" || fail "hephaestus.yaml has no brews entry named ark"
cat "$proj/hephaestus.yaml"
(
  cd "$proj"
  export HEPHAESTUS_ALLOW_FILE_URLS=1
  "${heph[@]}" check
  "${heph[@]}" build --tag "v$version" --fresh
  "${heph[@]}" formula --tag "v$version"
)
formula="$proj/dist/homebrew/ark.rb"
cat "$formula"

step "The formula is the release formula (only the URLs differ)"
grep -qx '  desc "Code intelligence MCP server for AI coding agents, with a repository text dump"' "$formula"
grep -qx '  homepage "https://github.com/magicdrive/ark"' "$formula"
grep -qx '  license "MIT"' "$formula"
[ "$(grep -c '^ *url "file://' "$formula")" = 4 ] || fail "want 4 url lines (darwin and linux, amd64 and arm64)"
! grep -q 'depends_on\|caveats\|post_install' "$formula" || fail "unexpected stanza"

step "Throw-away tap $tap"
brew tap-new --no-git "$tap" >/dev/null
if [[ "$trusts" == true ]]; then brew trust --tap "$tap"; fi
tapdir=$(brew --repository "$tap")
cp "$formula" "$tapdir/Formula/ark.rb"

step "brew style"
brew style "$tapdir/Formula/ark.rb"

step "brew audit --strict"
brew audit --strict --formula "$tap/ark"

step "brew install"
brew install --formula "$tap/ark"

step "brew test"
brew test "$tap/ark"

step "Installed executable and completions"
prefix=$(brew --prefix)
out=$("$prefix/bin/ark" --version)
[ "$out" = "ark version v$version" ] || fail "ark --version: $out"
"$prefix/bin/ark" --help >/dev/null
keg=$(brew --prefix "$tap/ark")
for pair in \
  "etc/bash_completion.d/ark:misc/completions/bash/ark-completion.bash" \
  "share/zsh/site-functions/_ark:misc/completions/zsh/_ark" \
  "share/fish/vendor_completions.d/ark.fish:misc/completions/fish/ark.fish"; do
  installed=${pair%%:*} src=${pair#*:}
  cmp "$keg/$installed" "$repo/$src" || fail "$installed differs from $src"
  [ -e "$prefix/$installed" ] || fail "$installed is not linked into $prefix"
done

step "brew uninstall"
brew uninstall "$tap/ark"
[ ! -e "$prefix/bin/ark" ] || fail "bin/ark left after uninstall"
for f in etc/bash_completion.d/ark share/zsh/site-functions/_ark share/fish/vendor_completions.d/ark.fish; do
  [ ! -e "$prefix/$f" ] || fail "$f left after uninstall"
done

echo
echo "ok: Homebrew E2E passed on $(uname -s)/$(uname -m)"
